<?php require 'config.php';$db=db();
if(($_POST['a']??'')=='login'){if(csrf_ok()&&getenv('ADMIN_PASS')&&hash_equals(getenv('ADMIN_PASS'),$_POST['pw']??''))$_SESSION['ok']=1;else $_SESSION['m']='รหัสผ่านไม่ถูกต้อง';header('Location: ./');exit;}
if(isset($_GET['out'])){session_destroy();header('Location: ./');exit;}
$H='<!doctype html><meta charset=utf-8><meta name=viewport content="width=device-width,initial-scale=1"><script src="https://cdn.tailwindcss.com/3.4.17"></script><body class="bg-slate-100 p-4"><div class="max-w-5xl mx-auto">';
if(empty($_SESSION['ok'])){echo $H.'<form method=post class="bg-white p-6 rounded-xl shadow max-w-sm mx-auto mt-20 space-y-3"><h1 class="font-bold text-lg">Make-up Class</h1><div class=text-red-600>'.h($_SESSION['m']??'').'</div><input type=hidden name=a value=login><input type=hidden name=t value="'.csrf().'"><input type=password name=pw placeholder="รหัสผ่านผู้ดูแล" class="border p-2 rounded w-full"><button class="bg-indigo-600 text-white px-4 py-2 rounded w-full">เข้าสู่ระบบ</button></form>';unset($_SESSION['m']);exit;}
if($_SERVER['REQUEST_METHOD']=='POST'&&csrf_ok()){try{$a=$_POST['a'];
 if($a=='student'){$s=$db->prepare('INSERT INTO students(name) VALUES(?) RETURNING id');$s->execute([trim($_POST['name'])]);$db->prepare('INSERT INTO credits(student_id,balance) VALUES(?,0)')->execute([$s->fetchColumn()]);}
 if($a=='topup')$db->prepare('UPDATE credits SET balance=balance+? WHERE student_id=?')->execute([(float)$_POST['n'],$_POST['sid']]);
 if($a=='absence'){$r=rule($_POST['course']);$ok=(strtotime($_POST['d'].' '.$_POST['tm'])-time())/3600>=$r['notice_hours'];
  $db->prepare('INSERT INTO absences(student_id,course,class_date,class_time,reason,eligible,note) VALUES(?,?,?,?,?,?,?)')->execute([$_POST['sid'],$_POST['course'],$_POST['d'],$_POST['tm'],$_POST['reason'],$ok?'t':'f',$ok?'':'แจ้งล่วงหน้าไม่ถึง '.$r['notice_hours'].' ชม.']);}
 if($a=='book'){$db->beginTransaction();$s=$db->prepare('SELECT * FROM absences WHERE id=? FOR UPDATE');$s->execute([$_POST['id']]);$ab=$s->fetch();
  [$ok,$m]=can_book($ab,$_POST['d'],$_POST['tm']);if(!$ok)throw new Exception($m);
  $db->prepare('INSERT INTO makeup_bookings(absence_id,student_id,slot_date,slot_time) VALUES(?,?,?,?)')->execute([$ab['id'],$ab['student_id'],$_POST['d'],$_POST['tm']]);
  $db->prepare("UPDATE absences SET status='booked' WHERE id=?")->execute([$ab['id']]);$db->commit();}
 if(in_array($a,['attend','noshow','cancel'])){$db->beginTransaction();$s=$db->prepare("SELECT b.*,x.course FROM makeup_bookings b JOIN absences x ON x.id=b.absence_id WHERE b.id=? AND b.status='booked' FOR UPDATE");$s->execute([$_POST['id']]);$b=$s->fetch();if(!$b)throw new Exception('ไม่พบการจองที่รออยู่');
  if($a=='attend'){$c=rule($b['course'])['cost_credits'];$u=$db->prepare('UPDATE credits SET balance=balance-? WHERE student_id=? AND balance>=?');$u->execute([$c,$b['student_id'],$c]);if(!$u->rowCount())throw new Exception('เครดิตไม่พอหักสิทธิ์');
   $db->prepare("UPDATE makeup_bookings SET status='attended',credit_used=? WHERE id=?")->execute([$c,$b['id']]);$db->prepare("UPDATE absences SET status='done' WHERE id=?")->execute([$b['absence_id']]);}
  if($a=='noshow'){$db->prepare("UPDATE makeup_bookings SET status='no_show' WHERE id=?")->execute([$b['id']]);$db->prepare("UPDATE absences SET status='done' WHERE id=?")->execute([$b['absence_id']]);}
  if($a=='cancel'){$db->prepare("UPDATE makeup_bookings SET status='cancelled' WHERE id=?")->execute([$b['id']]);$db->prepare("UPDATE absences SET status='open' WHERE id=?")->execute([$b['absence_id']]);}
  $db->commit();}
 if($a=='rule')$db->prepare('INSERT INTO makeup_rules(course,notice_hours,max_per_month,window_days,cost_credits) VALUES(?,?,?,?,?) ON CONFLICT(course) DO UPDATE SET notice_hours=EXCLUDED.notice_hours,max_per_month=EXCLUDED.max_per_month,window_days=EXCLUDED.window_days,cost_credits=EXCLUDED.cost_credits')->execute([trim($_POST['course']),$_POST['nh'],$_POST['mm'],$_POST['wd'],$_POST['cc']]);
 $_SESSION['m']='สำเร็จ';}catch(Throwable $e){if($db->inTransaction())$db->rollBack();$_SESSION['m']='ผิดพลาด: '.$e->getMessage();}
 header('Location: ?p='.urlencode($_GET['p']??'absences'));exit;}
$p=$_GET['p']??'absences';$T='<input type=hidden name=t value="'.csrf().'">';$in='border p-1 rounded';$bt='bg-indigo-600 text-white px-3 py-1 rounded';
echo $H.'<div class="flex gap-2 mb-3 items-center">';foreach(['absences'=>'แจ้งลา','bookings'=>'รอบชดเชย','credits'=>'เครดิต','rules'=>'กฎ'] as $k=>$v)echo '<a href="?p='.$k.'" class="px-3 py-1 rounded '.($p==$k?'bg-indigo-600 text-white':'bg-white').'">'.$v.'</a>';
echo '<a href="?out=1" class="ml-auto text-sm">ออกจากระบบ</a></div>';
if(!empty($_SESSION['m'])){echo '<div class="bg-amber-100 p-2 rounded mb-3">'.h($_SESSION['m']).'</div>';unset($_SESSION['m']);}
$st=$db->query('SELECT s.id,s.name,c.balance FROM students s LEFT JOIN credits c ON c.student_id=s.id ORDER BY s.name')->fetchAll();
$opts=implode('',array_map(fn($s)=>'<option value='.$s['id'].'>'.h($s['name']).'</option>',$st));
echo '<div class="bg-white p-4 rounded-xl shadow space-y-3">';
if($p=='absences'){echo '<form method=post class="flex flex-wrap gap-2">'.$T.'<input type=hidden name=a value=absence><select name=sid class="'.$in.'">'.$opts.'</select><input name=course placeholder="คอร์ส" required class="'.$in.'"><input type=date name=d required class="'.$in.'"><input type=time name=tm required class="'.$in.'"><input name=reason placeholder="เหตุผล" class="'.$in.'"><button class="'.$bt.'">แจ้งลา</button></form><table class="w-full text-sm"><tr class="text-left bg-slate-50"><th>นักเรียน</th><th>คอร์ส</th><th>วันที่ลา</th><th>สิทธิ์</th><th>จองรอบชดเชย</th></tr>';
 foreach($db->query('SELECT a.*,s.name FROM absences a JOIN students s ON s.id=a.student_id ORDER BY class_date DESC LIMIT 100') as $x){echo '<tr class=border-t><td>'.h($x['name']).'</td><td>'.h($x['course']).'</td><td>'.h($x['class_date']).' '.substr($x['class_time'],0,5).'</td><td>'.($x['eligible']?'✅':'❌ '.h($x['note'])).' · '.h($x['status']).'</td><td>';
  if($x['eligible']&&$x['status']=='open')echo '<form method=post class="flex gap-1">'.$T.'<input type=hidden name=a value=book><input type=hidden name=id value='.$x['id'].'><input type=date name=d required class="'.$in.'"><input type=time name=tm required class="'.$in.'"><button class="'.$bt.'">จอง</button></form>';echo '</td></tr>';}echo '</table>';}
if($p=='bookings'){echo '<table class="w-full text-sm"><tr class="text-left bg-slate-50"><th>นักเรียน</th><th>คอร์ส</th><th>รอบชดเชย</th><th>สถานะ</th><th></th></tr>';
 foreach($db->query('SELECT b.*,s.name,x.course FROM makeup_bookings b JOIN students s ON s.id=b.student_id JOIN absences x ON x.id=b.absence_id ORDER BY slot_date DESC,slot_time DESC LIMIT 100') as $x){echo '<tr class=border-t><td>'.h($x['name']).'</td><td>'.h($x['course']).'</td><td>'.h($x['slot_date']).' '.substr($x['slot_time'],0,5).'</td><td>'.h($x['status']).($x['credit_used']>0?' (หัก '.(float)$x['credit_used'].')':'').'</td><td>';
  if($x['status']=='booked')foreach(['attend'=>'มาเรียน (หักสิทธิ์)','noshow'=>'ไม่มา','cancel'=>'ยกเลิก'] as $k=>$v)echo '<form method=post class=inline>'.$T.'<input type=hidden name=a value='.$k.'><input type=hidden name=id value='.$x['id'].'><button class="'.$bt.' mr-1">'.$v.'</button></form>';echo '</td></tr>';}echo '</table>';}
if($p=='credits'){echo '<form method=post class="flex gap-2">'.$T.'<input type=hidden name=a value=student><input name=name placeholder="ชื่อนักเรียนใหม่" required class="'.$in.'"><button class="'.$bt.'">เพิ่มนักเรียน</button></form><table class="w-full text-sm"><tr class="text-left bg-slate-50"><th>นักเรียน</th><th>เครดิตคงเหลือ</th><th>เติมเครดิต</th></tr>';
 foreach($st as $s)echo '<tr class=border-t><td>'.h($s['name']).'</td><td>'.(float)$s['balance'].'</td><td><form method=post class="flex gap-1">'.$T.'<input type=hidden name=a value=topup><input type=hidden name=sid value='.$s['id'].'><input type=number step=0.5 name=n value=1 class="'.$in.' w-20"><button class="'.$bt.'">เติม</button></form></td></tr>';echo '</table>';}
if($p=='rules'){echo '<p class="text-sm text-slate-500">course = * คือกฎเริ่มต้น ใช้กับคอร์สที่ไม่มีกฎเฉพาะ</p><form method=post class="flex flex-wrap gap-2">'.$T.'<input type=hidden name=a value=rule><input name=course placeholder="คอร์ส หรือ *" required class="'.$in.'"><input type=number name=nh value=24 title="แจ้งล่วงหน้า (ชม.)" class="'.$in.' w-24"><input type=number name=mm value=2 title="ชดเชยได้/เดือน" class="'.$in.' w-24"><input type=number name=wd value=30 title="ต้องจองภายใน (วัน)" class="'.$in.' w-24"><input type=number step=0.5 name=cc value=1 title="เครดิตที่หัก" class="'.$in.' w-24"><button class="'.$bt.'">บันทึกกฎ</button></form><table class="w-full text-sm"><tr class="text-left bg-slate-50"><th>คอร์ส</th><th>แจ้งล่วงหน้า (ชม.)</th><th>ครั้ง/เดือน</th><th>จองภายใน (วัน)</th><th>หักเครดิต</th></tr>';
 foreach($db->query('SELECT * FROM makeup_rules ORDER BY course') as $r)echo '<tr class=border-t><td>'.h($r['course']).'</td><td>'.$r['notice_hours'].'</td><td>'.$r['max_per_month'].'</td><td>'.$r['window_days'].'</td><td>'.(float)$r['cost_credits'].'</td></tr>';echo '</table>';}
echo '</div></div>';
